// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  delayRender,
  continueRender,
} from '../remotionShim';
// Load Custom Brand Fonts
if (typeof document !== "undefined") {
  const loadCustomFont = (family: string, url: string) => {
    const handle = delayRender(`Loading ${family}`);
    const format = url.endsWith(".otf")
      ? "opentype"
      : url.endsWith(".woff2")
      ? "woff2"
      : url.endsWith(".woff")
      ? "woff"
      : "truetype";
    const font = new FontFace(family, `url('${url}') format('${format}')`);
    font
      .load()
      .then(() => {
        document.fonts.add(font);
        continueRender(handle);
      })
      .catch((err) => {
        console.log(`Error loading ${family}`, err);
        continueRender(handle);
      });
  };
  loadCustomFont(
    "Cytiva Aktiv",
    "https://assets.cytivalifesciences.com/fonts/CytivaAktiv_W_Bd.woff"
  );
}



export type ComponentNameProps = Record<string, any>;

// Pre-defined scattered indices for 17 tiles out of 100
const ACTIVE_INDICES = [
  12, 45, 8, 77, 33, 91, 24, 66, 3, 59, 82, 19, 50, 96, 38, 71, 5,
];

const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#18181b",
  transparentBackground = false,
  durationInSeconds = 8,
  gridColorBase = "#ffffff",
  gridColorActive = "#00886f",
  overlayText = "17%",
  overlayTextFontFamily = "Cytiva Aktiv",
  overlayTextFontSize = 240,
  subText1 = "of products showed an uplift",
  subText1FontFamily = "Cytiva Aktiv",
  subText1FontSize = 48,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Background safety
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timings (in frames)
  const gridComplete = Math.round(fps * 1.0); // 1 second
  const overlayStart = gridComplete;
  const overlayEnd = overlayStart + Math.round(fps * 0.4);
  const subText1Start = overlayEnd;
  const subText1End = subText1Start + Math.round(fps * 0.3);

  // Overlay Text Interpolation
  const overlayOpacity = interpolate(
    frame,
    [overlayStart, overlayEnd],
    [0, 0.85],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );
  const overlayScale = interpolate(
    frame,
    [overlayStart, overlayEnd],
    [0.95, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  // Subtext 1 Interpolation
  const subText1Opacity = interpolate(
    frame,
    [subText1Start, subText1End],
    [0, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );
  const subText1Y = interpolate(
    frame,
    [subText1Start, subText1End],
    [20, 0],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  // Render Grid
  const tiles = Array.from({ length: 100 }).map((_, i) => {
    const activeIndexPos = ACTIVE_INDICES.indexOf(i);
    const isActive = activeIndexPos !== -1;
    
    // Stagger illumination over the first second (gridComplete frames)
    const startF = isActive ? (activeIndexPos / 16) * gridComplete : 0;
    
    const activeProgress = spring({
      frame: frame - startF,
      fps,
      config: { damping: 14, stiffness: 120 },
    });

    return (
      <div
        key={i}
        style={{
          width: 64,
          height: 64,
          borderRadius: 6,
          position: "relative",
          overflow: "hidden",
          transition: "none",
        }}
      >
        {/* Base Tile (10% Opacity) */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            backgroundColor: gridColorBase,
            opacity: 0.1,
            transition: "none",
          }}
        />
        {/* Active Illuminated Overlay */}
        {isActive && (
          <div
            style={{
              position: "absolute",
              inset: 0,
              backgroundColor: gridColorActive,
              opacity: interpolate(activeProgress, [0, 1], [0, 1]),
              transform: `scale(${interpolate(
                activeProgress,
                [0, 1],
                [0.8, 1]
              )})`,
              transition: "none",
            }}
          />
        )}
      </div>
    );
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        alignItems: "center",
        justifyContent: "center",
        transition: "none",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          justifyContent: "center",
          gap: 120,
          width: "100%",
          padding: "0 5%",
          transition: "none",
        }}
      >
        {/* Left Container: Grid Layout */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(10, 1fr)",
            gap: 10,
            transition: "none",
          }}
        >
          {tiles}
        </div>

        {/* Right Container: Text Layout */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "flex-start",
            justifyContent: "center",
            maxWidth: "45%",
            transition: "none",
          }}
        >
          <span
            style={{
              fontFamily: overlayTextFontFamily,
              fontSize: overlayTextFontSize,
              fontWeight: "bold",
              color: "#ffffff",
              opacity: overlayOpacity,
              transform: `scale(${overlayScale})`,
              transformOrigin: "left center",
              margin: 0,
              padding: 0,
              lineHeight: 1,
              transition: "none",
            }}
          >
            {overlayText}
          </span>

          <div
            style={{
              marginTop: 24,
              opacity: subText1Opacity,
              transform: `translateY(${subText1Y}px)`,
              fontFamily: subText1FontFamily,
              fontSize: subText1FontSize,
              fontWeight: "normal",
              color: "#ffffff",
              textAlign: "left",
              transition: "none",
            }}
          >
            {subText1}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ComponentName;